INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'fr'), 'A1', 'greetings', 'Greetings', 'Greet your hosts and introduce yourself in French.', 'You arrive at a heritage home on Rue Dumas, in White Town. Madame Rosaline, your host, opens the door.', 'French is spoken by Franco-Pondicherrian families, at the Lycée français, the Alliance française and the French consulate. Use “vous” with people you have just met; “tu” is for friends and children.', 1, 'published', datetime('now'), datetime('now'), 1);
