INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'fr') AND slug = 'vous-and-tu'), (SELECT id FROM languages WHERE code = 'en'), '“Vous” and “tu”', 'Use “vous” (you, polite) with people you have just met, shopkeepers and older people: “Comment allez-vous ?”, “Vous pouvez répéter ?”. Use “tu” with friends, classmates and children: “Tu peux m''aider ?”.');
